  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']

    n = len(nodes)
    # build distance lookup
    dist_lookup = {}
    for a, b, d in distances:
        key = (a, b) if a <= b else (b, a)
        dist_lookup[key] = d

    edges = []
    for i in range(n):
        for j in range(i+1, n):
            a = nodes[i]
            b = nodes[j]
            d = dist_lookup[(a, b)]  # should exist
            w = max(core[a], core[b], d)
            # canonical ordering: a <= b lexicographically
            edges.append((a, b, w))

    # sort: primary by weight, then a, then b
    edges.sort(key=lambda e: (e[2], e[0], e[1]))

    # Union-Find
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total = 0.0
    for a, b, w in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total += w
            if len(mst_edges) == n - 1:
                break

    # (assume connected – fixtures guarantee it)
    return {
        'mst_edges': mst_edges,
        'total_weight': total
    }"
}
